// Digital products (downloadable files sold on /shop). A DigitalShelf IS a Shelf (kind "product", one-off, BUYABLE) plus the file facts.
// Generated by scripts/gen_digital_catalogue.mjs into lib/shop/digital_products.json. Types only.
import type { Shelf } from "./types";

export type DigitalFacts = {
  description: string;
  whatsIncluded: string[];
  requirements: string[];
  deliveryFiles: string[];
  disclaimers: string[];
  filename: string;
  fileSize: string;
  sha256: string;
};
export type DigitalShelf = Shelf & { digital: DigitalFacts };
